<p><a href="/family"><?= e(t('Family shared board & guardian reports')) ?></a></p>
<details class="card"><summary><?= e(t('Guardian XP and badge settings')) ?></summary><form class="form-grid" method="post" action="/school/xp/settings"><?= csrf_field() ?><?php foreach(['homework','chores','syllabus','mistakes']as $k): ?><label><?= e(ucfirst($k)) ?> <?= e(t('XP')) ?><input type="number" name="<?= e($k) ?>" min="1" max="100" value="<?= e(Db::setting('school_xp_'.$k,'10')) ?>" required></label><?php endforeach; ?><label><?= e(t('Daily XP cap')) ?><input type="number" name="daily_cap" min="1" max="1000" value="<?= e(Db::setting('school_xp_daily_cap','100')) ?>" required></label><label><?= e(t('XP per level')) ?><input type="number" name="level_every" min="10" max="1000" value="<?= e(Db::setting('school_level_every','100')) ?>" required></label><label><?= e(t('Special badge name')) ?><input name="badge_title" maxlength="80" value="<?= e(Db::setting('school_badge_title','Learning champion')) ?>" required></label><label><?= e(t('Badge earned at XP')) ?><input type="number" name="badge_at" min="10" max="10000" value="<?= e(Db::setting('school_badge_at','500')) ?>" required></label><label><?= e(t('Linked guardian')) ?><select name="guardian"><?php foreach(class_exists('ProfileManager')?ProfileManager::guardians():[]as $g): ?><option value="<?= e($g['id']) ?>"><?= e($g['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Guardian PIN (or profile PIN when no guardian is linked)')) ?><input type="password" name="guardian_pin" required autocomplete="off"></label><button><?= e(t('Verify & save rules')) ?></button></form></details>
<?php if($kind==='reading'||$kind==='reading_goals'): ?><section class="card"><h2><?= e(t('Reading progress')) ?></h2><?php foreach(SchoolService::rows('reading_goals')as $goal):$g=$goal['fields'];$pages=0;foreach(SchoolService::rows('reading')as $log)if(mb_strtolower($log['fields']['book'])===mb_strtolower($g['book']))$pages+=$log['fields']['pages']; ?><p><?= e($g['title']) ?> · <?= e($pages) ?> / <?= e($g['target_pages']) ?> <?= e(t('pages ·')) ?> <?= e(min(100,round($pages/$g['target_pages']*100))) ?><?= e(t('% · Due')) ?> <?= e($g['due']) ?></p><?php endforeach; ?></section><?php endif; ?>
<?php if($kind==='tuition_attendance'): ?><section class="card"><h2><?= e(t('Tuition attendance')) ?></h2><?php foreach(SchoolService::rows('tuition')as $class):$present=0;$total=0;foreach(SchoolService::rows('tuition_attendance')as $a)if($a['fields']['class']===$class['id']&&$a['fields']['state']!=='excused'){$total++;if($a['fields']['state']==='present')$present++;} ?><p><?= e($class['fields']['title']) ?> · <?= e($present) ?>/<?= e($total) ?> <?= e(t('classes')) ?><?= $total?' · '.e(round($present/$total*100,1)).'%':'' ?></p><?php endforeach; ?></section><?php endif; ?>
<?php if($kind==='rewards'): ?><section class="card"><h2><?= e(t('Redeem approved rewards')) ?></h2><?php foreach(Db::all("SELECT r.*,d.redeemed_at FROM school_reward_requests r LEFT JOIN school_reward_redemptions d ON d.request_id=r.id WHERE r.status='approved' ORDER BY r.id DESC")as $r): ?><p><?= e(t('Reward #')) ?><?= e($r['reward_id']) ?> · <?= e($r['cost']) ?> <?= e(t('XP')) ?><?= $r['redeemed_at']?' · Redeemed '.e($r['redeemed_at']):'' ?></p><?php if(!$r['redeemed_at']): ?><form class="inline" method="post" action="/school/reward/redeem"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= e($r['id']) ?>"><label><?= e(t('Guardian')) ?><select name="guardian" required><?php foreach(class_exists('ProfileManager')?ProfileManager::guardians():[]as $g): ?><option value="<?= e($g['id']) ?>"><?= e($g['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Guardian PIN')) ?><input type="password" name="guardian_pin" required></label><button><?= e(t('Confirm received reward')) ?></button></form><?php endif; ?><?php endforeach; ?></section><?php endif; ?>
